    (b.val : ZMod (2^255 - 19)) + (256 : ZMod (2^255 - 19)) * acc

def U8x64_as_Nat (bytes : Array U8 64#usize) : Nat :=
  ∑ i ∈ Finset.range 64, 2^(8 * i) * (bytes[i]!).val

